No other text, explanation, or markdown - just the raw JSON array.`, maxTurns: 5, workingDir: '/transcripts' }) }}

parameters.jsCode:
const response = $json.result;

const match = response.match(/\[[\s\S]*\]/);
if (!match) {
  throw new Error('No JSON array found in response: ' + response.substring(0, 200));
}

const files = JSON.parse(match[0]);
console.log(`Found ${files.length} VTT files`);

return files.map(filename => ({
  json: {
    filename,
    outputPath: `/transcripts/summaries/${filename.replace('.vtt', '.md')}`
  }
}));

const items = $input.all();
const successCount = items.filter(item => item.json.success).length;

return [{
  json: {
    stage: 'individual_analysis_complete',
    filesProcessed: items.length,
    successCount: successCount,
    timestamp: new Date().toISOString()
  }
}];

// Initialize loop counter for extended quality loop
// This loop now encompasses Coverage Metrics through Quality Reviewers
return [{
  json: {
    iteration: 1,
    maxIterations: 3
  }
}];

// Aggregate all review results with error handling

// Safely get iteration count - check multiple possible sources
function safeGetIteration() {
  try {
    const init = $('Init Quality Loop');
    if (init?.item?.json?.iteration) return init.item.json.iteration;
  } catch (e) {}
  try {
    const inc = $('Increment Counter');
    if (inc?.item?.json?.iteration) return inc.item.json.iteration;
  } catch (e) {}
  return 1;
}

const iteration = safeGetIteration();

// Parse review results (handle potential JSON in markdown)
function parseReview(result) {
  if (!result) {
    return { overall_pass: false, issues: ['No result provided'], recommendations: [] };
  }
  try {
    return JSON.parse(result);
  } catch (e) {
    const match = result.match?.(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch (e2) {}
    }
    return { overall_pass: false, issues: ['Could not parse review response'], recommendations: [] };
  }
}

// Safely get node output with error handling
function safeGetNodeResult(nodeName) {
  try {
    const nodeOutput = $(nodeName);
    if (!nodeOutput?.item?.json?.result) {
      return { overall_pass: false, issues: [`Node '${nodeName}' has no valid output`], recommendations: [] };
    }
    return parseReview(nodeOutput.item.json.result);
  } catch (e) {
    const errorMsg = e?.message || String(e);
    return { overall_pass: false, issues: [`Node '${nodeName}' failed: ${errorMsg}`], recommendations: [] };
  }
}

const contentReview = safeGetNodeResult('Content Accuracy Reviewer');
const visualReview = safeGetNodeResult('Visual Design Reviewer');
const technicalReview = safeGetNodeResult('Technical Quality Reviewer');

const allPass = contentReview.overall_pass && visualReview.overall_pass && technicalReview.overall_pass;

const allIssues = [
  ...(contentReview.issues || []),
  ...(visualReview.issues || []),
  ...(technicalReview.issues || [])
];

const allRecommendations = [
  ...(contentReview.recommendations || []),
  ...(visualReview.recommendations || []),
  ...(technicalReview.recommendations || [])
];

return [{
  json: {
    allPass,
    iteration,
    maxIterations: 3,
    shouldContinue: !allPass && iteration < 3,
    reviews: {
      content: contentReview,
      visual: visualReview,
      technical: technicalReview
    },
    allIssues,
    allRecommendations,
    totalIssueCount: allIssues.length
  }
}];

// Increment iteration counter
const currentIteration = $('Aggregate Reviews').item.json.iteration;
const newIteration = currentIteration + 1;

return [{
  json: {
    iteration: newIteration,
    maxIterations: 3,
    previousIssueCount: $('Aggregate Reviews').item.json.totalIssueCount
  }
}];

// Merge node to handle both paths (pass and max iterations)
// Get data from whichever path we came from
const items = $input.all();
const aggregateData = items.find(item => item.json.reviews) || { json: {} };
const iterationData = items.find(item => item.json.iteration && !item.json.reviews) || { json: {} };

const finalIteration = aggregateData.json.iteration || iterationData.json.iteration || 'unknown';
const allPassed = aggregateData.json.allPass || false;
const maxedOut = iterationData.json.iteration >= 3;

return [{
  json: {
    qualityLoopComplete: true,
    finalIteration,
    allPassed,
    maxIterationsReached: maxedOut && !allPassed,
    reviews: aggregateData.json.reviews || null
  }
}];

const qualityData = $('Quality Loop Complete').item.json;

let status = 'Pipeline Complete';
if (qualityData.allPassed) {
  status = 'Pipeline Complete - All Quality Checks Passed';
} else if (qualityData.maxIterationsReached) {
  status = 'Pipeline Complete - Max Iterations Reached (Review quality-report.md)';
}

return [{
  json: {
    status,
    qualityLoop: {
      iterations: qualityData.finalIteration,
      allPassed: qualityData.allPassed,
      maxIterationsReached: qualityData.maxIterationsReached
    },
    outputs: {
      individualSummaries: '/transcripts/summaries/*.md',
      combinedAnalysis: '/transcripts/combined-analysis.md',
      dashboard: '/transcripts/dashboard.html'
    },
    note: 'Output paths relative to your configured transcripts directory',
    completedAt: new Date().toISOString()
  }
}];
